-- U3 Directory and Settings: tables, constraints, indexes, reach helpers and row-level policies
-- (BR30.1, BR30.5, BR30.8, BR30.9, NFR1.25, NFR1.26, NFR3.6).
-- Schema-neutral and pinned like the U1 and U2 files: the migration runner sets the session search path
-- to the target schema and every function pins its own schema with `set search_path from current`.
-- Conventions (U1 BR3.1): uuid keys generated by the database, `organization_id` on every table, integer
-- `version` on records people change at the same time (raised by one on every accepted update through
-- `platform_touch_version`), timestamps in UTC (timestamptz). Inside Directory the tables are linked by
-- composite foreign keys (id plus organization), so a child row can never belong to another organization
-- than its parent. Links to other blocks (Settings and Coordination to Directory, Parent to Identity's
-- Account) are typed ids with no foreign key (ADR-001), checked inside the named functions.
-- Every table starts with no right for any application role; signed-in accounts get select only, and
-- every change goes through the named functions of the next file. The service-role key gets nothing.

create table organizations (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 1 and 200),
  status text not null default 'active' check (status in ('active', 'archived')),
  created_at timestamptz not null default now()
);

create table school_years (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references organizations (id),
  name text not null check (char_length(name) between 1 and 100),
  starts_on date not null,
  ends_on date not null,
  status text not null default 'active' check (status in ('active', 'archived')),
  version integer not null default 1 check (version >= 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (ends_on >= starts_on),
  unique (id, organization_id)
);
create unique index school_years_name_unique on school_years (organization_id, lower(name));
create trigger school_years_touch_version before update on school_years
  for each row execute function platform_touch_version();

create table groups (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  school_year_id uuid not null,
  name text not null check (char_length(name) between 1 and 100),
  status text not null default 'active' check (status in ('active', 'archived')),
  version integer not null default 1 check (version >= 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (school_year_id, organization_id) references school_years (id, organization_id),
  unique (id, organization_id)
);
create unique index groups_name_unique on groups (school_year_id, lower(name));
create index groups_organization on groups (organization_id, status);
create trigger groups_touch_version before update on groups
  for each row execute function platform_touch_version();

create table families (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references organizations (id),
  display_name text not null check (char_length(display_name) between 1 and 200),
  status text not null default 'active' check (status in ('active', 'archived')),
  archived_at timestamptz,
  version integer not null default 1 check (version >= 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check ((status = 'archived') = (archived_at is not null)),
  unique (id, organization_id)
);
create index families_organization on families (organization_id, status);
create trigger families_touch_version before update on families
  for each row execute function platform_touch_version();

-- A family's membership of a group. At most one active membership per family and group; an ended one
-- stays as history.
create table group_memberships (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  family_id uuid not null,
  group_id uuid not null,
  status text not null default 'active' check (status in ('active', 'ended')),
  created_at timestamptz not null default now(),
  ended_at timestamptz,
  check ((status = 'ended') = (ended_at is not null)),
  foreign key (family_id, organization_id) references families (id, organization_id),
  foreign key (group_id, organization_id) references groups (id, organization_id)
);
create unique index group_memberships_one_active on group_memberships (family_id, group_id)
  where status = 'active';
create index group_memberships_family on group_memberships (family_id, status);
create index group_memberships_group on group_memberships (group_id, status);

-- account_id is the typed id of Identity's Account: empty until the person accepts an invitation; the
-- unique constraint makes a second link of the same account impossible even in a race (BR30.3).
create table parents (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  family_id uuid not null,
  account_id uuid unique,
  display_name text not null check (char_length(display_name) between 1 and 200),
  optional_profile text check (optional_profile is null or char_length(optional_profile) <= 500),
  optional_profile_consent boolean not null default false,
  status text not null default 'active' check (status in ('active', 'archived')),
  version integer not null default 1 check (version >= 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- The profile text is stored only with consent (BR30.4).
  check (optional_profile_consent or optional_profile is null),
  foreign key (family_id, organization_id) references families (id, organization_id),
  unique (id, organization_id)
);
create index parents_family on parents (family_id);
create trigger parents_touch_version before update on parents
  for each row execute function platform_touch_version();

-- Contact details live apart from the parent so one policy can hide them as a whole (FR3.4, BR30.5).
create table parent_contacts (
  parent_id uuid primary key,
  organization_id uuid not null,
  contact_email text check (contact_email is null or (
    contact_email = lower(contact_email) and char_length(contact_email) <= 254
    and contact_email ~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$')),
  contact_phone text check (contact_phone is null or contact_phone ~ '^[0-9 +-]{6,20}$'),
  locality text check (locality is null or char_length(locality) <= 100),
  updated_at timestamptz not null default now(),
  foreign key (parent_id, organization_id) references parents (id, organization_id)
);

create table children (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  family_id uuid not null,
  display_name text not null check (char_length(display_name) between 1 and 200),
  status text not null default 'active' check (status in ('active', 'archived')),
  version integer not null default 1 check (version >= 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (family_id, organization_id) references families (id, organization_id)
);
create index children_family on children (family_id);
create trigger children_touch_version before update on children
  for each row execute function platform_touch_version();

-- Settings (owned by the Settings block): the organization is a typed id, not a foreign key.
create table organization_settings (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  key text not null check (char_length(key) between 1 and 100 and key ~ '^[a-z0-9_.]+$'),
  value text not null check (char_length(value) <= 500),
  version integer not null default 1 check (version >= 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (organization_id, key)
);
create trigger organization_settings_touch_version before update on organization_settings
  for each row execute function platform_touch_version();

create table reminder_settings (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  threshold text not null default 'default' check (char_length(threshold) between 1 and 100 and threshold ~ '^[a-z0-9_.]+$'),
  recipient_scope text not null default 'duty' check (recipient_scope in ('duty', 'group')),
  enabled boolean not null default true,
  version integer not null default 1 check (version >= 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (organization_id, threshold)
);
create trigger reminder_settings_touch_version before update on reminder_settings
  for each row execute function platform_touch_version();

-- ---------------------------------------------------------------------------------------------------
-- Reach helpers. Written once and reused by the policies here, by Coordination's policies and by the
-- use-case functions. Every one requires an active session (U2 BR2.6), so a deactivated or signed-out
-- account reaches nothing. They are executable by signed-in accounts because the policies call them.
-- ---------------------------------------------------------------------------------------------------

-- The family of the signed-in parent: the Parent linked to the session's account, in an active family.
-- Internal: the elevated functions use it to find "the actor's family" (BR32.2).
create or replace function directory_actor_family() returns uuid
language sql stable security definer set search_path from current
as $$
  select p.family_id
    from parents p join families f on f.id = p.family_id
   where p.account_id = auth.uid() and p.status = 'active' and f.status = 'active'
     and current_session_is_active()
$$;

create or replace function directory_is_family_parent(p_family_id uuid) returns boolean
language sql stable security definer set search_path from current
as $$ select coalesce(p_family_id = directory_actor_family(), false) $$;

create or replace function directory_in_organization(p_organization_id uuid) returns boolean
language sql stable security definer set search_path from current
as $$ select current_session_is_active() and exists (
  select 1 from accounts a where a.id = auth.uid() and a.organization_id = p_organization_id) $$;

-- An admin of the organization: a super admin, or a group admin of at least one group.
create or replace function directory_is_admin(p_organization_id uuid) returns boolean
language sql stable security definer set search_path from current
as $$ select current_session_is_active() and (
  has_super_scope(p_organization_id)
  or exists (select 1 from app_role_grants g
              where g.subject_id = auth.uid() and g.revoked_at is null and g.organization_id = p_organization_id
                and g.role = 'group_admin' and g.scope_type = 'group')) $$;

-- The group reach of a family (entities.md, "Placeholder tables"): a super admin reaches the whole
-- organization; a group admin reaches a family through an active membership in a group where they hold a
-- grant. A family without a membership is reached by super admins only.
create or replace function directory_reaches_family(p_organization_id uuid, p_family_id uuid) returns boolean
language sql stable security definer set search_path from current
as $$ select current_session_is_active() and (
  has_super_scope(p_organization_id)
  or exists (select 1 from group_memberships m
              where m.family_id = p_family_id and m.organization_id = p_organization_id and m.status = 'active'
                and has_current_role_scope('group_admin', p_organization_id, 'group', m.group_id))) $$;

-- Who may read a group: super admins, the group's admins and teachers, and the parents of families that
-- are active members of it (BR30.8, BR30.9).
create or replace function directory_group_visible(p_organization_id uuid, p_group_id uuid) returns boolean
language sql stable security definer set search_path from current
as $$ select current_session_is_active() and (
  has_super_scope(p_organization_id)
  or has_current_role_scope('group_admin', p_organization_id, 'group', p_group_id)
  or has_current_role_scope('kindergarten_teacher', p_organization_id, 'group', p_group_id)
  or exists (select 1 from group_memberships m
              where m.group_id = p_group_id and m.organization_id = p_organization_id and m.status = 'active'
                and m.family_id = directory_actor_family())) $$;

create or replace function directory_school_year_visible(p_organization_id uuid, p_school_year_id uuid) returns boolean
language sql stable security definer set search_path from current
as $$ select current_session_is_active() and (
  has_super_scope(p_organization_id)
  or exists (select 1 from groups g
              where g.school_year_id = p_school_year_id and g.organization_id = p_organization_id
                and directory_group_visible(g.organization_id, g.id))) $$;

-- Contact details are readable by the parent, the other parents of the same family and admins in reach
-- (BR30.5); nobody else, teachers and other families included.
create or replace function directory_can_read_contact(p_organization_id uuid, p_parent_id uuid) returns boolean
language sql stable security definer set search_path from current
as $$ select current_session_is_active() and exists (
  select 1 from parents p
   where p.id = p_parent_id and p.organization_id = p_organization_id
     and (directory_is_family_parent(p.family_id) or directory_reaches_family(p.organization_id, p.family_id))) $$;

-- A parent's optional profile text (BR30.4): the parent themself and admins in reach, only with consent.
-- Other parents, even of the same family, get nothing. The text is not a column right of the parents
-- table for the same reason: a policy cannot hide one column from one reader.
create or replace function directory_parent_profile(p_parent_id uuid) returns text
language sql stable security definer set search_path from current
as $$ select p.optional_profile
    from parents p
   where p.id = p_parent_id and current_session_is_active() and p.optional_profile_consent
     and (p.account_id = auth.uid() or directory_reaches_family(p.organization_id, p.family_id)) $$;

-- ---------------------------------------------------------------------------------------------------
-- Row-level security. No insert, update or delete policy exists: every change is made by a named
-- function of the next file (BR30.1).
-- ---------------------------------------------------------------------------------------------------
alter table organizations enable row level security;
alter table school_years enable row level security;
alter table groups enable row level security;
alter table families enable row level security;
alter table group_memberships enable row level security;
alter table parents enable row level security;
alter table parent_contacts enable row level security;
alter table children enable row level security;
alter table organization_settings enable row level security;
alter table reminder_settings enable row level security;

create policy organizations_read on organizations for select to authenticated
  using (directory_in_organization(id));
create policy school_years_read on school_years for select to authenticated
  using (directory_school_year_visible(organization_id, id));
create policy groups_read on groups for select to authenticated
  using (directory_group_visible(organization_id, id));
create policy families_read on families for select to authenticated
  using (directory_is_family_parent(id) or directory_reaches_family(organization_id, id));
create policy group_memberships_read on group_memberships for select to authenticated
  using (directory_is_family_parent(family_id) or directory_reaches_family(organization_id, family_id));
create policy parents_read on parents for select to authenticated
  using (directory_is_family_parent(family_id) or directory_reaches_family(organization_id, family_id));
create policy parent_contacts_read on parent_contacts for select to authenticated
  using (directory_can_read_contact(organization_id, parent_id));
create policy children_read on children for select to authenticated
  using (directory_is_family_parent(family_id) or directory_reaches_family(organization_id, family_id));
create policy organization_settings_read on organization_settings for select to authenticated
  using (directory_is_admin(organization_id));
create policy reminder_settings_read on reminder_settings for select to authenticated
  using (directory_is_admin(organization_id));

-- Table rights: select only, and never the optional profile text (read through directory_parent_profile).
revoke all on organizations, school_years, groups, families, group_memberships, parents, parent_contacts,
  children, organization_settings, reminder_settings from public, anon, authenticated, service_role;
grant select on organizations, school_years, groups, families, group_memberships, parent_contacts,
  children, organization_settings, reminder_settings to authenticated;
grant select (id, organization_id, family_id, account_id, display_name, optional_profile_consent,
              status, version, created_at, updated_at)
  on parents to authenticated;

-- Function rights: the helpers the policies call and the profile read are executable by signed-in
-- accounts; the actor-family lookup is internal.
revoke all on function
  directory_actor_family(),
  directory_is_family_parent(uuid),
  directory_in_organization(uuid),
  directory_is_admin(uuid),
  directory_reaches_family(uuid, uuid),
  directory_group_visible(uuid, uuid),
  directory_school_year_visible(uuid, uuid),
  directory_can_read_contact(uuid, uuid),
  directory_parent_profile(uuid)
  from public, anon, authenticated, service_role;
grant execute on function
  directory_is_family_parent(uuid),
  directory_in_organization(uuid),
  directory_is_admin(uuid),
  directory_reaches_family(uuid, uuid),
  directory_group_visible(uuid, uuid),
  directory_school_year_visible(uuid, uuid),
  directory_can_read_contact(uuid, uuid),
  directory_parent_profile(uuid)
  to authenticated;
